  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03","C04","C07","C12","C15","C20","C23","C29","C42"],
  "claims": [
    {
      "claim": "The query is a fluoroquinolone with N1-fluorocyclopropyl, C6-F, C8-Cl, and C7 amino-pyrrolidine substituents; all fluoroquinolone L1 contexts show oral bioavailability above 20%: moxifloxacin 91% (C04), trovafloxacin 87.6% (C03, C23), levofloxacin and ofloxacin approaching 100% (C07, C12, C15), antofloxacin high (C09, C22), and norfloxacin mean 40% (C20).",
      "card_ids": ["C03","C04","C07","C09","C10","C12","C15","C20","C22","C23"]
    },
    {
      "claim": "New L2 records reinforce the high prediction: moxifloxacin absolute bioavailability was 86% in 12 healthy volunteers after an overnight fast (C42) and model estimates were 97.1% to 99.8% (C27, C30, C39, C46); ofloxacin absolute bioavailability is virtually 100% when fasted (C29); trovafloxacin is about 88% fasting (C35); antofloxacin oral-to-IV AUC ratio is about 1.1 (C36).",
      "card_ids": ["C27","C29","C30","C35","C36","C39","C42","C46"]
    },
    {
      "claim": "No L1 or L2 record provides affirmative evidence for F below 20%; the lowest fluoroquinolone value remains norfloxacin at 22-60% with mean 40% (C20).",
      "card_ids": ["C20"]
    },
    {
      "claim": "Ziprasidone fed-state records around 60% (C25, C26, C28, C31, C34, C38, C40, C44, C45) and haloperidol 35±8% (C08, C18) also exceed 20%, but these non-quinolone contexts carry less weight than the direct fluoroquinolone evidence.",
      "card_ids": ["C08","C18","C25","C26","C28","C31","C34","C38","C40","C44","C45"]
    },
    {
      "claim": "The physicochemical prior of full ionization and low logD is not affirmative evidence of low F; fluoroquinolones are zwitterionic yet achieve high oral bioavailability (C04, C07, C12, C29, C42).",
      "card_ids": ["C04","C07","C12","C29","C42"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C25","C26","C27","C28","C29","C30","C31","C32","C34","C35","C36","C37","C38","C39","C40","C42","C43","C44","C45","C46"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific formulation, dose, or prandial-state data are available.",
    "No direct first-pass, efflux, or transporter data exist for the exact C7 spiro-pyrrolidine, C8-Cl, and N1-fluorocyclopropyl combination.",
    "C24 concerns elbasvir and grazoprevir, and C33 and C41 are relative bioavailability comparisons for bictegravir; these are not applicable to the fluoroquinolone query.",
    "Norfloxacin shows class variability with mean F about 40%, but it remains above the 20% threshold."
  ],
  "decision_summary": "The query is a fluoroquinolone and all relevant L1 and L2 records from fluoroquinolone contexts show oral bioavailability well above 20%: moxifloxacin 86-99% (C04, C27, C30, C39, C42, C46), trovafloxacin 87.6-88% (C03, C10, C23, C35), levofloxacin and ofloxacin about 100% (C07, C12, C15, C29), antofloxacin high (C09, C22, C36, C43), and norfloxacin mean 40% (C20). No record provides affirmative evidence for F below 20%. The low physicochemical prior is not endpoint proof and is outweighed by class-consistent high bioavailability evidence. Prediction remains high and confidence is strengthened."
}

